"""Offline NetNomos finite-domain command line."""
import json
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parent
sys.path.insert(0, str(ROOT))

from netnomos.finite import compile_job


def main():
    batch = json.load(sys.stdin)
    result = {"results": [compile_job(job) for job in batch["jobs"]]}
    json.dump(result, sys.stdout, separators=(",", ":"))
    sys.stdout.write("\n")


if __name__ == "__main__":
    main()
